<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {request} from '../api'
import PhotoGallery from './PhotoGallery.vue'
import PrivatePreview from '../admin/PrivatePreview.vue'
import {entryNames} from '../writing/entries'
const data=ref<any>({items:[],total:0}),albums=ref<any[]>([]),admin=ref(false),error=ref(''),page=ref(1)
const year=ref(''),month=ref(''),record=ref(''),place=ref(''),kind=ref(''),album=ref('')
const optionRecords=ref<any[]>([]),optionPlaces=ref<any[]>([]),recordQ=ref(''),placeQ=ref('')
async function options(){try{const r=await request('/photos/options?record_q='+encodeURIComponent(recordQ.value)+'&place_q='+encodeURIComponent(placeQ.value));optionRecords.value=r.records;optionPlaces.value=r.places}catch{error.value='读取筛选选项失败'}}
const saving=ref(false)
const draft=ref<any>(),editing=ref(''),selected=ref<string[]>([])
async function load(){try{const p=new URLSearchParams({page:String(page.value)});for(const [key,v] of Object.entries({year:year.value,month:month.value,record_id:record.value,place_id:place.value,kind:kind.value,album_id:album.value}))if(v)p.set(key,v);data.value=await request('/photos?'+p);albums.value=await request('/photos/albums');error.value=''}catch{error.value='读取相册失败，请核对筛选后重试'}}
onMounted(async()=>{await load();await options();try{admin.value=(await request('/admin/status')).is_admin}catch{}})
function toggle(id:string){const i=selected.value.indexOf(id);if(i<0)selected.value.push(id);else selected.value.splice(i,1)}
async function edit(id=''){try{editing.value=id;draft.value=id?await request('/admin/photo-albums/'+id):{name:'',media_ids:[...selected.value],cover_id:selected.value[0]||null,expected_revision:0};for(const id of selected.value)if(!draft.value.media_ids.includes(id))draft.value.media_ids.push(id)}catch{error.value='读取相册配置失败'}}
function move(i:number,d:number){const a=draft.value.media_ids;[a[i],a[i+d]]=[a[i+d],a[i]]}
async function save(){if(saving.value)return;saving.value=true;try{await request('/admin/photo-albums'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:JSON.stringify(draft.value)});draft.value=undefined;selected.value=[];await load()}catch{error.value='保存失败或相册已被其他页面修改，请保留输入并重新核对'}finally{saving.value=false}}
async function remove(){if(!draft.value||!editing.value)return;try{await request('/admin/photo-albums/'+editing.value+'?expected_revision='+draft.value.expected_revision,{method:'DELETE'});draft.value=undefined;album.value='';await load()}catch{error.value='删除失败，请核对相册版本'}}
</script>
<template><main class="photo-stream"><RouterLink to="/">返回首页</RouterLink><h1>生活相册</h1><p>照片复用现有媒体，日期来自照片标注、拍摄日期或明确的单日文章；日期范围不代表确切拍摄日。</p><form class="photo-filters" @submit.prevent="page=1;load()"><label>年份<input v-model="year" type="number" min="1" max="9999"/></label><label>月份<select aria-label="月份" v-model="month"><option value="">全部月份</option><option v-for="n in 12" :value="String(n)">{{n}} 月</option></select></label><label>专题<select aria-label="专题" v-model="kind"><option value="">全部专题</option><option v-for="(name,k) in entryNames" :value="k">{{name}}</option></select></label><label>查找文章<input v-model="recordQ"/></label><label>查找地点<input v-model="placeQ"/></label><button type="button" @click="options">查找筛选项</button><label>文章<select aria-label="文章" v-model="record"><option value="">全部文章</option><option v-for="r in optionRecords" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>地点<select aria-label="地点" v-model="place"><option value="">全部地点</option><option v-for="p in optionPlaces" :key="p.id" :value="p.id">{{p.name}} · {{p.city}}</option></select></label><label>手工相册<select aria-label="手工相册" v-model="album"><option value="">全部照片</option><option v-for="a in albums" :value="a.id">{{a.name}}</option></select></label><button>筛选</button></form><p role="status">{{error}}</p><div v-if="admin" class="actions"><span>已选 {{selected.length}} 张</span><button @click="edit()">建立相册</button><button v-if="album" @click="edit(album)">编辑此相册</button></div><section v-if="draft" class="album-editor"><h2>{{editing?'编辑相册':'新相册'}}</h2><label>相册名称<input v-model="draft.name" maxlength="200"/></label><div v-for="(id,i) in draft.media_ids" :key="id"><PrivatePreview :id="id" alt="相册图片"/><button type="button" :aria-pressed="draft.cover_id===id" @click="draft.cover_id=id">{{draft.cover_id===id?'当前封面':'设为封面'}}</button><button :disabled="i===0" @click="move(Number(i),-1)">上移</button><button :disabled="Number(i)===draft.media_ids.length-1" @click="move(Number(i),1)">下移</button><button @click="draft.media_ids.splice(i,1);draft.cover_id===id&&(draft.cover_id=null)">移除关联</button></div><footer><button :disabled="saving" @click="save">保存相册</button><button class="quiet" @click="draft=undefined">取消</button><button v-if="editing" class="quiet" @click="remove">删除相册（保留照片）</button></footer></section><PhotoGallery :photos="data.items" layout="grid" group-by="none"/><section v-for="p in data.items" :key="p.id" class="photo-sources"><PrivatePreview v-if="admin" :id="p.id" :alt="p.alt"/><label v-if="admin"><input type="checkbox" :checked="selected.includes(p.id)" @change="toggle(p.id)"/>选择此照片</label><p>{{p.date||'确切日期未知'}}</p><div v-for="r in p.records" :key="r.id"><RouterLink :to="'/posts/'+r.id">{{r.title}}</RouterLink> · {{r.date_source==='article-range-unknown'?r.range_start+' 至 '+r.range_end+'（范围回退）':r.date}}</div></section><div class="actions"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>{{page}}</span><button :disabled="page*24>=data.total" @click="page++;load()">下一页</button></div></main></template>
<style scoped>.photo-stream{padding:24px;max-width:1100px;margin:auto;min-width:0}.photo-filters{display:flex;flex-wrap:wrap;gap:12px}.photo-filters label{width:180px;max-width:100%}.photo-filters input,.photo-filters select{width:100%;box-sizing:border-box}.photo-sources{padding:10px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.photo-sources>img{width:120px;max-width:100%;height:auto}.photo-sources input{width:auto}.album-editor{padding:16px;border:1px solid var(--line)}.album-editor img{width:120px;max-width:100%}.album-editor footer{position:sticky;bottom:0;padding:12px;background:var(--paper);display:flex;gap:8px;flex-wrap:wrap}</style>
